// ObservedAtLT applies the LT predicate on the "observed_at" field.
func ObservedAtLT(v time.Time) predicate.Observation {
	return predicate.Observation(sql.FieldLT(FieldObservedAt, v))
}

// ObservedAtLTE applies the LTE predicate on the "observed_at" field.
func ObservedAtLTE(v time.Time) predicate.Observation {
	return predicate.Observation(sql.FieldLTE(FieldObservedAt, v))
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Observation) predicate.Observation {
	return predicate.Observation(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Observation) predicate.Observation {
	return predicate.Observation(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Observation) predicate.Observation {
	return predicate.Observation(sql.NotPredicates(p))
}
